#include <iostream>



#include <vector>



#include <string>



#include <sstream>



#include <algorithm>



#include <iomanip>



using namespace std;



vector<long long> parse(const string &s){istringstream in(s);vector<long long>a;long long x;while(in>>x)a.push_back(x);return a;}



void printLines(const vector<long long>&a){for(auto v:a)cout<<v<<'\n';}



void printRow(const vector<long long>&a){for(size_t i=0;i<a.size();i++){if(i)cout<<' ';cout<<a[i];}cout<<'\n';}



string avg(long long sum,long long n,int places){



 if(n==0)return string("0.")+string(places,'0');



 long long scale=1;for(int i=0;i<places;i++)scale*=10;



 long long absS=sum<0?-sum:sum;



 long long v=(2*absS*scale+n)/(2*n);



 ostringstream s;if(sum<0&&v)s<<'-';s<<v/scale<<'.'<<setw(places)<<setfill('0')<<(v%scale);return s.str();



}



int digits(long long v){if(v<0)v=-v;int s=0;do{s+=v%10;v/=10;}while(v);return s;}



int main(){ios::sync_with_stdio(false);cin.tie(nullptr);



string line;getline(cin,line);vector<long long>a=parse(line);



bool yes=true;for(auto v:a)if(v<=0)yes=false;cout<<(yes?"YES":"NO")<<'\n';
